#!/usr/bin/env python3
"""Run unchanged main-branch baseline_test, retaining original setup semantics."""
import csv,hashlib,json,os,resource,shutil,signal,subprocess,sys,time
from datetime import datetime,timezone
from pathlib import Path
OUT=Path(__file__).resolve().parent;ROOT=Path('/root/Openfhe_PE')
sys.path.insert(0,str(OUT/'tools'));import monitor_helpers as mon
RINGS=[16384,32768];CASES=[(3,64,56),(8,128,28),(12,256,14),(16,512,7)]
def now():return datetime.now(timezone.utc).isoformat()
def save(path,obj):
 t=path.with_suffix(path.suffix+'.tmp');t.write_text(json.dumps(obj,indent=2)+'\n');t.replace(path)
def report():
 results=[]
 for n in RINGS:
  for layer,c,h in CASES:
   f=OUT/f'ring{n}/layer{layer}/result.json'
   if f.exists():results.append(json.loads(f.read_text()))
 lines=['# Original main-branch fully encrypted baseline reproduction','',f'Updated UTC: {now()}','',
 '## Provenance and exact scope','',
 'Repository main branch at commit 08e56ef. The original src/main.cpp baseline_test entry, Conv2d_C and Relu_appx are executed, without the feature-branch convolution adapters or normalized polynomials. The main-branch worktree remains clean. The sole build compatibility addition is the missing conv2d_l.hpp declaration header copied into an external include directory from the feature branch; no classes from that header are instantiated by this entry. Build/output files live outside the repository.','',
 'Each process runs one fully encrypted synthetic convolution followed by the original polynomial activation + EvalBootstrap call. Input/output channel counts are 64, 128, 256 or 512 and input widths 56, 28, 14 or 7. Original Conv2d_C does not implement padding: outputs are 54, 26, 12 and 5, not the same-padding shapes of the previous adapted baseline. BN is not part of this original baseline_test entry. Inputs and filters are generated by the original deterministic rand()/9 routines, not by ResNet inference or trained convolution weights. The layer index labels identify representative shapes only.','',
 '## Original parameters and initialization','',
 'Ring 16384 or 32768, slots=N/2, scaling/first moduli 30/40 bits, HYBRID numLargeDigits=3. Depth is computed as GetBootstrapDepth({3,3}, UNIFORM_TERNARY)+3 (23 in this installed library). Actual bootstrap setup uses budget {4,3}, correction factor 10. The inconsistency between the two budgets is preserved. Threads: 96, nested teams disabled via environment.','',
 'The original code always generates bootstrap keys and also sets USE_SS=true unconditionally. Consequently approximation runs also initialize FHEW, its bootstrap key, and CKKS/FHEW scheme-switching keys, even though the baseline activation is Relu_appx. This extra resident setup is deliberately preserved; it is a concrete difference from the earlier approximation-only adapters and a possible explanation for historical memory near 90 GiB.','',
 'Original Relu_appx evaluates its unnormalized degree-6 polynomial and calls EvalBootstrap inside the channel-parallel loop. The original call is not forced to start from depleted ciphertexts; OpenFHE can return the input if the refresh does not improve the tower count. Thus an EvalBootstrap call is not proof that levels were refreshed. No FHEW activation is executed by baseline_test.','',
 '## Measurement limits','',
 'GNU time measures whole-process wall time and lifetime peak RSS. Operator timings are parsed from the original model\'s Layer 0/1 messages; activation includes both polynomial and bootstrap call and cannot be split without changing the entry. Phase labels in rss.csv are inferred from log milestones with 0.5-second sampling, not instrumentation inside old code. Prediction time includes the original model\'s final decryption/printing. Whole-process wall also includes data/weight loading, synthetic generation and original validation/printing. No allocator trimming. A host MemAvailable guard stops a case below 12 GiB; failures are retained and not counted as successful runs.','',
 'The original final check compares polynomial output against exact ReLU, so its reported average relative loss is a model approximation metric, not a cryptographic arithmetic check. Zero exit status alone does not establish acceptable activation accuracy.','',
 '| Representative layer | C | Input/output H×W | Ring / slots | Status | Conv (s) | Poly + bootstrap call (s) | Prediction (s) | Process wall (s) | Lifetime peak (GiB) | Setup-phase sampled max (GiB) |','|---:|---:|---|---|---|---:|---:|---:|---:|---:|---:|']
 for n in RINGS:
  for layer,c,h in CASES:
   r=next((r for r in results if r['ring']==n and r['layer']==layer),None)
   if not r:lines.append(f'| {layer} | {c} | {h}×{h} / {h-2}×{h-2} | {n} / {n//2} | pending / running | — | — | — | — | — | — |');continue
   fmt=lambda k:f"{r[k]:.3f}" if r.get(k) is not None else '—'
   setup=r.get('phase_memory',{}).get('key_setup',{}).get('peak_gib',0)
   lines.append(f"| {layer} | {c} | {h}×{h} / {h-2}×{h-2} | {n} / {n//2} | {r['status']} | {fmt('conv_s')} | {fmt('activation_s')} | {fmt('prediction_s')} | {r['wall_s']:.3f} | {r['peak_gib']:.3f} | {setup:.3f} |")
 lines+=['','Raw files per case: run.log, rss.csv, time.txt, command.json and result.json. configuration.json records source commit, build parameters and executable hash. Source snapshots are retained in source/.']
 t=OUT/'REPORT.md.tmp';t.write_text('\n'.join(lines)+'\n');t.replace(OUT/'REPORT.md');save(OUT/'summary.json',results)
def run(binary,n,layer,c,h):
 folder=OUT/f'ring{n}/layer{layer}';folder.mkdir(parents=True,exist_ok=True)
 command=[str(binary),'--model','baseline_test','--ringDim',str(n),'--batch',str(n//2),'--act','1','--top','0','--bottom',str(h-1),'--left','0','--right',str(h-1),'--nums',str(c)]
 save(folder/'command.json',dict(command=command,cwd=str(ROOT/'build'),started_utc=now()))
 env=os.environ.copy();env.update(LD_LIBRARY_PATH='/root/local/openFHE/lib:/root/local/cnpy/lib',OMP_NUM_THREADS='96',OMP_DYNAMIC='FALSE',OMP_MAX_ACTIVE_LEVELS='1')
 phase='key_setup';samples=[];phase_events=[];conv=activation=prediction=loss=None;offset=0;pending='';pressure=False;lastreport=0;start=time.monotonic()
 import re
 with (folder/'run.log').open('w') as log,(folder/'rss.csv').open('w',newline='') as rss:
  writer=csv.DictWriter(rss,fieldnames=['utc','elapsed_s','phase','layer','rss_gib','process_peak_gib','threads']);writer.writeheader()
  proc=subprocess.Popen(['/usr/bin/time','-f','wall_seconds=%e\npeak_rss_kib=%M\nexit_code=%x','-o',str(folder/'time.txt'),*command],stdout=log,stderr=subprocess.STDOUT,cwd=ROOT/'build',env=env,start_new_session=True)
  while proc.poll() is None:
   try:
    with (folder/'run.log').open(errors='replace') as read:
     read.seek(offset);data=read.read();offset=read.tell()
    pending+=data;parts=pending.split('\n');pending=parts.pop()
    for line in parts:
     newphase=phase
     if 'Shape of input_3d:' in line:newphase='input_preparation'
     if line.strip()=='conv1 forward':newphase='server_conv'
     if line.strip()=='relu1 forward':newphase='server_relu'
     m=re.search(r'Layer (\d+) forward pass took ([\d.eE+-]+) ms',line)
     if m:
      if m[1]=='0':conv=float(m[2])/1000
      if m[1]=='1':activation=float(m[2])/1000;newphase='verification'
     m=re.search(r'prediction time: ([\d.eE+-]+)ms',line)
     if m:prediction=float(m[1])/1000
     m=re.search(r'average percentage loss: (.+)',line)
     if m:
      try:loss=float(m[1])
      except ValueError:pass
     if newphase!=phase:phase=newphase;phase_events.append(dict(elapsed_s=time.monotonic()-start,phase=phase))
    kids=Path(f'/proc/{proc.pid}/task/{proc.pid}/children').read_text().split();info=mon.rss(int(kids[0])) if kids else {}
    if 'VmRSS' in info:
     sample=dict(utc=now(),elapsed_s=time.monotonic()-start,phase=phase,layer=layer,rss_gib=info['VmRSS']/1024**2,process_peak_gib=info['VmHWM']/1024**2,threads=info['Threads']);samples.append(sample);writer.writerow(sample);rss.flush()
     save(OUT/'live.json',dict(status='running',ring=n,channels=c,model_pid=int(kids[0]),runner_pid=os.getpid(),**sample))
    if mon.available()<12:
     pressure=True;os.killpg(proc.pid,signal.SIGTERM)
     try:proc.wait(timeout=15)
     except subprocess.TimeoutExpired:os.killpg(proc.pid,signal.SIGKILL);proc.wait()
    if time.monotonic()-lastreport>30:report();lastreport=time.monotonic()
   except (OSError,KeyError,ValueError):pass
   time.sleep(.5)
  code=proc.wait()
 # Read final milestones even when the process exits between samples.
 text=(folder/'run.log').read_text(errors='replace')
 for index,key in [('0','conv'),('1','activation')]:
  matches=re.findall(r'Layer '+index+r' forward pass took ([\d.eE+-]+) ms',text)
  if matches:
   if key=='conv':conv=float(matches[-1])/1000
   else:activation=float(matches[-1])/1000
 matches=re.findall(r'prediction time: ([\d.eE+-]+)ms',text)
 if matches:prediction=float(matches[-1])/1000
 matches=re.findall(r'average percentage loss: ([^\n]+)',text)
 if matches:
  try:loss=float(matches[-1])
  except ValueError:pass
 metrics=dict(line.split('=',1) for line in (folder/'time.txt').read_text().splitlines() if '=' in line)
 result=dict(ring=n,layer=layer,channels=c,input_width=h,output_width=h-2,status='memory_pressure' if pressure else 'success' if code==0 and conv is not None and activation is not None else 'failed',exit_code=code,finished_utc=now(),conv_s=conv,activation_s=activation,prediction_s=prediction,average_relative_loss=loss,wall_s=float(metrics.get('wall_seconds',time.monotonic()-start)),peak_gib=float(metrics.get('peak_rss_kib',0))/1024**2,phase_memory={p:mon.summarize([x for x in samples if x['phase']==p]) for p in ['key_setup','input_preparation','server_conv','server_relu','verification']},phase_events=phase_events)
 save(folder/'result.json',result);report();print('CASE_FINISHED',n,layer,result['status'],flush=True);return result

def main():
 resource.setrlimit(resource.RLIMIT_CORE,(0,0));binary=OUT/'build/test'
 source=OUT/'source';source.mkdir(exist_ok=True)
 for p in ['src/main.cpp','src/cnn/conv2d.cpp','src/cnn/conv2d.hpp','src/cnn/activation.cpp','src/cnn/model.cpp','src/encryption/encryption.cpp','CMakeLists.txt']:shutil.copy2(ROOT/p,source/Path(p).name)
 save(OUT/'configuration.json',dict(branch='main',source_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),started_utc=now(),runner_pid=os.getpid(),rings=RINGS,shapes=CASES,slots='N/2',depth=23,scale_bits=30,first_bits=40,digits=3,bootstrap_setup_budget=[4,3],depth_computation_budget=[3,3],both_bootstrap_and_scheme_switch_keys=True,threads=96,entry='baseline_test, original unmodified main',binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest()))
 report();results=[]
 for n in RINGS:
  for layer,c,h in CASES:
   results.append(run(binary,n,layer,c,h))
   if results[-1]['status']=='memory_pressure':save(OUT/'live.json',dict(status='memory_pressure',result=results[-1]));return
 status='finished' if all(r['status']=='success' for r in results) else 'finished_with_failures'
 save(OUT/'completion.json',dict(status=status,finished_utc=now()));save(OUT/'live.json',dict(status=status,finished_utc=now()));report()
if __name__=='__main__':main()
